public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Step 1: Create a new graph
    Graph<V, E> graph = new Graph<>();

    // Step 2: Add vertices to the graph
    for (String vertexName : resultMap.keySet()) {
        V vertex = resultMap.get(vertexName);
        graph.addVertex(vertex);
    }

    // Step 3: Add edges to the graph
    for (String vertexName1 : resultMap.keySet()) {
        V vertex1 = resultMap.get(vertexName1);
        for (String vertexName2 : resultMap.keySet()) {
            V vertex2 = resultMap.get(vertexName2);
            if (vertex1 != vertex2) {
                E edge = new Edge<>(vertex1, vertex2);
                graph.addEdge(edge);
            }
        }
    }

    // Step 4: Set the graph as the target graph
    target.setGraph(graph);
}

