        }
    }
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Invalid input: out, message, schema, and buffer must not be null");
    }

    int size = schema.getSerializedSize(message);
    int prefixSize = CodedOutputStream.computeRawVarint32Size(size);
    int totalSize = prefixSize + size;

    CodedOutputStream cos = CodedOutputStream.newInstance(out, buffer);
    cos.writeRawVarint32(size);
    schema.writeTo(cos, message);
    cos.flush();

    return totalSize;
}

