}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Validate input
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings cannot be null");
    }

    // Step 2: Get the current index mappings
    Mappings currentMappings = getCurrentIndexMappings(tableName);

    // Step 3: Diff the mappings
    Mappings diffMappings = new Mappings();
    for (Mapping mapping : mappings.getMappings()) {
        if (!currentMappings.contains(mapping)) {
            diffMappings.add(mapping);
        }
    }

    // Step 4: Remove _source config
    diffMappings.remove("_source");

    return diffMappings;
}

