public long readLong(final int offset) {
    // Step 1: Check if the offset is valid
    if (offset < 0 || offset >= this.data.length) {
        throw new IndexOutOfBoundsException("Offset is out of bounds: " + offset);
    }

    // Step 2: Read the value at the given offset
    long value = this.data[offset];

    // Step 3: Check if the value is a valid long value
    if (value < Long.MIN_VALUE || value > Long.MAX_VALUE) {
        throw new IllegalArgumentException("Value is not a valid long value: " + value);
    }

    // Step 4: Return the read value
    return value;
}

public boolean equals(final byte[] data, int offset, final int len) {
    if (data == null || offset < 0 || len < 0 || offset + len > data.length) {
        return false;
    }
    for (int i = 0; i < len; i++) {
        if (data[offset + i] != this.data[i]) {
            return false;
        }
    }
    return true;
}

