static long compressTimeBucket(long timeBucket, int dayStep) {
    // Step 1: Check if the input time bucket is valid
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Invalid time bucket: " + timeBucket);
    }

    // Step 2: Calculate the number of days to add to the time bucket
    int daysToAdd = dayStep - (int) (timeBucket % dayStep);

    // Step 3: Add the calculated number of days to the time bucket
    timeBucket += daysToAdd;

    // Step 4: Return the re-formatted time bucket
    return timeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("Length out of bounds");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            size += 4;
            i++;
        } else {
            size += 3;
        }
    }
    return size;
}

