public void removeFromTreeEdgeList() {
    if (this.prevInTree == null && this.nextInTree == null) {
        // This edge is not in any tree edge list, so there is nothing to do.
        return;
    }

    if (this.prevInTree != null) {
        // Remove this edge from the previous edge's nextInTree list.
        this.prevInTree.nextInTree = this.nextInTree;
    }

    if (this.nextInTree != null) {
        // Remove this edge from the next edge's prevInTree list.
        this.nextInTree.prevInTree = this.prevInTree;
    }

    // Update this edge's prevInTree and nextInTree to null.
    this.prevInTree = null;
    this.nextInTree = null;
}

