private void putAbstractTypes(final int start, final int end) {
    // Step 1: Validate input parameters
    if (start < 0 || start >= currentFrame.length) {
        throw new IllegalArgumentException("Invalid start index: " + start);
    }
    if (end < 0 || end > currentFrame.length || end <= start) {
        throw new IllegalArgumentException("Invalid end index: " + end);
    }

    // Step 2: Write the abstract types to the stack map table entries
    for (int i = start; i < end; i++) {
        StackMapTableEntry entry = new StackMapTableEntry();
        entry.setFrameType(currentFrame[i].getFrameType());
        entry.setOffsetDelta(currentFrame[i].getOffsetDelta());
        entry.setLocals(currentFrame[i].getLocals());
        entry.setStack(currentFrame[i].getStack());
        stackMapTableEntries.add(entry);
    }
}

