  // Fill the buffer with the input stream
  int bytesRead;
  while ((bytesRead = in.read(this.buffer)) != -1) {
    this.buffer = Arrays.copyOf(this.buffer, this.buffer.length + bytesRead);
  }

  // Reset the read pointer to the start of the byte array
  this.readPointer = 0;
}

