public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 2) {
    return 2;
  }
  int prime = 3;
  while (prime < desiredCapacity) {
    if (isPrime(prime)) {
      return prime;
    }
    prime += 2;
  }
  return prime;
}

