public final byte[] toByteArray() {
    // Step 1: Check if the buffer is empty
    if (buffer.isEmpty()) {
        return new byte[0];
    }

    // Step 2: Calculate the total size of the buffer
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
        totalSize += buffer.remaining();
    }

    // Step 3: Create a new byte array with the total size
    byte[] bytes = new byte[totalSize];

    // Step 4: Copy the contents of each buffer into the byte array
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int remaining = buffer.remaining();
        buffer.get(bytes, offset, remaining);
        offset += remaining;
    }

    return bytes;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                if (next == 'n') {
                    sb.append('\n');
                    i++;
                } else if (next == 'r') {
                    sb.append('\r');
                    i++;
                } else if (next == 't') {
                    sb.append('\t');
                    i++;
                } else if (next == 'b') {
                    sb.append('\b');
                    i++;
                } else if (next == 'f') {
                    sb.append('\f');
                    i++;
                } else if (next == '\\') {
                    sb.append('\\');
                    i++;
                } else if (next == 'u') {
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 5;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                } else {
                    throw new Exception("Invalid escape sequence");
                }
            } else {
                throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

