final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Step 1: Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.size()) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Step 2: Check if the char buffer is large enough to hold the string
    if (charBuffer.length < constantPool.get(constantPoolEntryIndex).getSize()) {
        throw new IllegalArgumentException("Char buffer is not large enough to hold the string");
    }

    // Step 3: Read the string from the constant pool entry
    ConstantUtf8 constantUtf8 = (ConstantUtf8) constantPool.get(constantPoolEntryIndex);
    String string = constantUtf8.getBytes();

    // Step 4: Copy the string to the char buffer
    System.arraycopy(string.toCharArray(), 0, charBuffer, 0, string.length());

    return string;
}

