    if (node == null) {
        return false;
    }

    ListNodeImpl<E> previous = node.previous;
    ListNodeImpl<E> next = node.next;

    if (previous == null) {
        // Node is the head of the list
        head = next;
    } else {
        previous.next = next;
    }

    if (next == null) {
        // Node is the tail of the list
        tail = previous;
    } else {
        next.previous = previous;
    }

    node.previous = null;
    node.next = null;

    return true;
}

