private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty.");
    }
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        int current = bounds.get(i);
        totalSum += current;
        suffixSum.add(totalSum);
    }
    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
  if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
    throw new IllegalArgumentException("Invalid input");
  }

  int i = from;
  int j = to;
  while (i < j) {
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
    i++;
    j--;
  }
}

