public ByteVector putInt(final int intValue) {
  // Step 1: Check if the byte vector is large enough to hold the int value
  if (this.data.length < this.wpos + 4) {
    // If the byte vector is not large enough, resize it
    byte[] newData = new byte[this.wpos + 4];
    System.arraycopy(this.data, 0, newData, 0, this.wpos);
    this.data = newData;
  }

  // Step 2: Put the int value into the byte vector
  this.data[this.wpos++] = (byte) (intValue >>> 24);
  this.data[this.wpos++] = (byte) (intValue >>> 16);
  this.data[this.wpos++] = (byte) (intValue >>> 8);
  this.data[this.wpos++] = (byte) intValue;

  return this;
}

