}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Step 1: Check if the type variable has a bound
    if (typeVariable.getBounds().length == 0) {
        return Unknown.class;
    }

    // Step 2: Get the first bound
    Type bound = typeVariable.getBounds()[0];

    // Step 3: Check if the bound is a class or interface
    if (bound instanceof Class || bound instanceof ParameterizedType) {
        return bound;
    } else {
        // If the bound is a type variable, we need to resolve it recursively
        return resolveBound((TypeVariable<?>) bound);
    }
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }

    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph contains all the vertices in the set
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Check if the graph is connected
    if (!isConnected(graph)) {
        return false;
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

