    // Step 1: Parse the descriptor to determine the number of types to pop
    int numTypes = parseDescriptor(descriptor);

    // Step 2: Pop the types from the output frame stack
    for (int i = 0; i < numTypes; i++) {
        outputFrameStack.pop();
    }
}

private int parseDescriptor(final String descriptor) {
    // Step 1: Split the descriptor into its component parts
    String[] parts = descriptor.split("\\(");

    // Step 2: Determine the number of types to pop
    int numTypes = 0;
    if (parts.length == 2) {
        // Method descriptor, pop the argument types
        String[] argTypes = parts[1].split("\\)");
        numTypes = argTypes.length;
    } else {
        // Type descriptor, pop the type itself
        numTypes = 1;
    }

    return numTypes;
}

